import { lookup } from 'node:dns/promises';
import { request } from 'node:https';
import { isIP } from 'node:net';
import { SafeError } from './errors.js';

// This transport has no arbitrary request tool. Callers must first select a
// source-reviewed operation, then pass a canonical URL generated by that adapter.
export function publicAddress(address: string): boolean {
  if (isIP(address) !== 4) return false; // Fail closed for IPv6, including mapped addresses.
  const p = address.split('.').map(Number);
  const a=p[0]!, b=p[1]!;
  return !(a===0 || a===10 || a===127 || a>=224 || (a===169 && b===254) || (a===172 && b>=16 && b<=31) || (a===192 && (b===168 || b===0 || b===2)) || (a===100 && b>=64 && b<=127) || (a===198 && (b===18 || b===19 || b===51)) || (a===203 && b===0));
}
export function requireHttps(url: URL, hosts: readonly string[]): void {
  if (url.protocol !== 'https:' || url.username || url.password || url.port || url.hash || !hosts.includes(url.hostname) || isIP(url.hostname)) {
    throw new SafeError('NETWORK_POLICY', 'URL is outside the reviewed HTTPS host allowlist.');
  }
}
export async function requestBytes(url: URL, hosts: readonly string[], headers: Record<string,string>, maxBytes: number, body?: string): Promise<Buffer> {
  requireHttps(url, hosts);
  const addresses = await Promise.race([lookup(url.hostname, {all:true, family:4}), new Promise<never>((_,reject)=>{const timer=setTimeout(()=>reject(new SafeError('TIMEOUT','DNS resolution timed out.')),5000);timer.unref();})]);
  if (!addresses.length || addresses.some(x => !publicAddress(x.address))) throw new SafeError('NETWORK_POLICY', 'Host did not resolve exclusively to public addresses.');
  const pinned = addresses[0]!;
  return new Promise((resolve,reject) => {
    let done=false;
    const fail=(error: SafeError) => { if (!done) {done=true;clearTimeout(deadline);reject(error);} };
    const deadline=setTimeout(()=>{req.destroy();fail(new SafeError('TIMEOUT','Remote operation timed out.'));},20_000);
    const req=request(url,{method:body===undefined?'GET':'POST',headers,agent:false,family:4,lookup:(_host,_options,callback)=>callback(null,pinned.address,4)},res=>{
      // Never follow redirects; credentials cannot migrate to another origin.
      if (res.statusCode !== 200) {res.destroy();fail(new SafeError('HTTP_ERROR',`Remote operation returned status ${res.statusCode ?? 0}; redirects are disabled.`));return;}
      const chunks:Buffer[]=[];let size=0;
      res.on('data',(chunk:Buffer)=>{size+=chunk.length;if(size>maxBytes){res.destroy();fail(new SafeError('SIZE_LIMIT','Response exceeded the download limit.'));}else chunks.push(chunk);});
      res.on('end',()=>{if(!done){done=true;clearTimeout(deadline);resolve(Buffer.concat(chunks));}});
      res.on('error',()=>fail(new SafeError('NETWORK_ERROR','Remote response interrupted.')));
    });
    req.setTimeout(15_000,()=>{req.destroy();fail(new SafeError('TIMEOUT','Remote operation timed out.'));});
    req.on('error',()=>fail(new SafeError('NETWORK_ERROR','Remote operation could not be completed.')));
    req.end(body);
  });
}
